shader:
// Plugin Example — a worked example of a local effect plugin.
//
// Tints the image toward a hue, using the shared blend-mode library so
// this also exercises the `// INCLUDE_BLEND_MODES` splice.
//   params[0] = amount (0-1)
//   params[1] = hue shift (0-1)
//   params[2] = blend_mode

struct EffectParams {
    params: array<vec4<f32>, 12>,
    width: u32,
    height: u32,
    _padding: vec2<f32>,
}

fn get_param(index: u32) -> f32 {
    return effect_params.params[index / 4u][index % 4u];
}

struct VertexOutput {
    @builtin(position) position: vec4<f32>,
    @location(0) uv: vec2<f32>,
}

@group(0) @binding(0) var input_texture: texture_2d<f32>;
@group(0) @binding(1) var input_sampler: sampler;
@group(0) @binding(2) var<uniform> effect_params: EffectParams;

// INCLUDE_BLEND_MODES

@vertex
fn vs_main(@builtin(vertex_index) vertex_index: u32) -> VertexOutput {
    var output: VertexOutput;
    let x = f32((vertex_index & 1u) << 2u);
    let y = f32((vertex_index & 2u) << 1u);
    output.position = vec4<f32>(x - 1.0, 1.0 - y, 0.0, 1.0);
    output.uv = vec2<f32>(x * 0.5, y * 0.5);
    return output;
}

@fragment
fn fs_main(input: VertexOutput) -> @location(0) vec4<f32> {
    let amount = get_param(0u);
    let hue = get_param(1u);
    let blend_mode = i32(get_param(2u));

    let original = textureSample(input_texture, input_sampler, input.uv);

    // Uses `luminance` and `hsl_to_rgb` from the shared library — the
    // reason `requires_blend_modes` is true, and the reason a missing
    // splice would fail to compile naming a function nobody wrote.
    let l = luminance(original.rgb);
    let tint = hsl_to_rgb(vec3<f32>(hue, 0.6, l));

    let result = apply_blend(original.rgb, tint, blend_mode, amount);
    return vec4<f32>(result, original.a);
}
